#!/system/bin/sh
# Config is generated by TPCapture. It contains paths and public settings only.
set -u
umask 077
MODDIR=${0%/*}
[ ! -f "$MODDIR/disable" ] && [ ! -f "$MODDIR/remove" ] || exit 0
[ -r "$MODDIR/config.sh" ] && [ -r "$MODDIR/targets.txt" ] || exit 0
. "$MODDIR/config.sh"
# Magisk BusyBox standalone mode can resolve applet names rather than paths.
# Use the platform shell and restore the PATH captured when the module was installed.
savedPath='';[ ! -r "$MODDIR/root-path" ] || IFS= read -r savedPath < "$MODDIR/root-path" || :
ANDROID_ROOT=${ANDROID_ROOT:-/system}
PATH="${savedPath:+$savedPath:}$ANDROID_ROOT/bin:$ANDROID_ROOT/xbin:/vendor/bin:/sbin${PATH:+:$PATH}"
export PATH
unset ASH_STANDALONE
SYSTEM_SH=$ANDROID_ROOT/bin/sh
[ -x "$SYSTEM_SH" ] || SYSTEM_SH=sh
mkdir -p -m 700 "$APPCAPTURE_DATA_DIR" || exit 0
LOG=$APPCAPTURE_DATA_DIR/autostart.log
log(){ printf '%s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*" >> "$LOG"; }
export APPCAPTURE_DATA_DIR TPCAPTURE_CA_MODE TPCAPTURE_UDP
case "${1:-}" in early) attempts=1;;service) attempts=30;;*)exit 0;;esac
[ -f "$BACKEND_SCRIPT" ] || { log '找不到 TPCapture 后端脚本';exit 0; }
version=$("$SYSTEM_SH" "$BACKEND_SCRIPT" version 2>/dev/null) || version=''
[ "$version" = "$EXPECTED_VERSION" ] || { log '后端版本已变化，请在 App 更新自启动模块';exit 0; }
set --
while IFS= read -r target;do [ -n "$target" ] || continue;set -- "$@" "$target";done < "$MODDIR/targets.txt"
[ "$#" -gt 0 ] || { log '没有自启动目标';exit 0; }
bootID=$(cat /proc/sys/kernel/random/boot_id 2>/dev/null || :)
[ -n "$bootID" ] || { log '无法读取启动标识';exit 0; }
n=0
while [ "$n" -lt "$attempts" ];do
  [ ! -f "$MODDIR/disable" ] && [ ! -f "$MODDIR/remove" ] || exit 0
  stopped='';[ ! -r "$APPCAPTURE_DATA_DIR/.autostart-stopped-boot" ] || IFS= read -r stopped < "$APPCAPTURE_DATA_DIR/.autostart-stopped-boot" || :
  [ "$stopped" != "$bootID" ] || { log '本次启动中已手动停止';exit 0; }
  current=$("$SYSTEM_SH" "$BACKEND_SCRIPT" status 2>/dev/null || :)
  if printf '%s\n' "$current" | grep -qE '^running count=[[:space:]]*[1-9][0-9]*' &&
     iptables -t mangle -C OUTPUT -j TPC_SINGLE_OUT >/dev/null 2>&1 &&
     ip6tables -t mangle -C OUTPUT -j TPC_SINGLE_OUT >/dev/null 2>&1;then
    log '后端已运行';exit 0
  fi
  action=start
  marker=$APPCAPTURE_DATA_DIR/.autostart-session-boot
  if [ "$CREATE_SESSION" = 1 ];then
    previous='';[ ! -r "$marker" ] || IFS= read -r previous < "$marker" || :
    [ "$previous" = "$bootID" ] || action=new-session-start
  fi
  log "尝试启动: $action"
  if output=$("$SYSTEM_SH" "$BACKEND_SCRIPT" "$action" "$@" 2>&1);then result=0;else result=$?;fi
  [ -z "$output" ] || printf '%s\n' "$output" >> "$LOG"
  if [ "$action" = new-session-start ];then
    case "$output" in *'archived='*|*'no current database'*)printf '%s\n' "$bootID" > "$marker";;esac
  fi
  [ "$result" = 0 ] && { log '启动完成';exit 0; }
  n=$((n+1));[ "$n" -lt "$attempts" ] || break;sleep 2
done
log '未能自动启动，请在 App 查看状态'
exit 0
